                  await edit(n, note.id, lines.join("\n"));
                }
              }
            }
          } catch (err) {
            console.log("terragucci: " + cmd + " failed: " + err.message);
            if (cmd === "oidc") process.exit(1);
          }' -- "$@"; }
          terragucci comment --layers 'network;app' --out terragucci-comment.json || exit 1
          read -r TG_PR TG_SHA TG_BASE TG_ROOT <<EOF
          $(node -e 'const d=JSON.parse(require("fs").readFileSync(process.argv[1],"utf-8"));console.log(d.go?[d.pr,d.sha,d.base,d.root||"-"].join(" "):"")' terragucci-comment.json)
          EOF
          [ -n "$TG_PR" ] || exit 0
          [ "$TG_ROOT" = "-" ] && TG_ROOT=""
          export TG_PR TG_SHA TG_ROOT TG_BASE="origin/$TG_BASE"
          git fetch --quiet origin "refs/pull/$TG_PR/head" || { echo "terragucci: could not fetch the pull request head" >&2; exit 1; }
